<!doctype html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f172a"><link rel="manifest" href="/trainingapp/public/manifest.json"><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="/trainingapp/public/css/app.css"><title>FitTrack — Treningi</title></head>
<body class="bg-slate-50 text-slate-900"><main class="mx-auto max-w-3xl px-4 pb-28 pt-6 space-y-6">
<header><a class="text-sm font-bold text-slate-500" href="/trainingapp/">← FitTrack</a><h1 class="mt-2 text-3xl font-black">Plany treningowe</h1><p class="mt-1 text-slate-500">Twórz i edytuj plany, ustawiaj kolejność ćwiczeń, serie, powtórzenia i przerwy.</p><a href="/trainingapp/exercises.php" class="mt-4 inline-flex items-center gap-2 rounded-xl border border-slate-300 bg-white px-4 py-3 font-bold shadow-sm">☷ Zarządzaj bazą ćwiczeń <span class="text-slate-500">→</span></a></header>

<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4"><div class="flex items-center justify-between gap-3"><h2 id="planFormTitle" class="text-xl font-bold">Utwórz nowy plan</h2><button id="cancelPlanEdit" type="button" class="hidden rounded-xl border px-3 py-2 text-sm font-bold">Anuluj edycję</button></div><form id="planForm" class="space-y-3"><input type="hidden" name="id"><label class="block text-sm font-semibold">Nazwa planu<input name="name" required maxlength="150" class="mt-1 w-full rounded-xl border p-3" placeholder="np. FBW A"></label><label class="block text-sm font-semibold">Opis<textarea name="description" rows="2" class="mt-1 w-full rounded-xl border p-3" placeholder="Opcjonalny opis"></textarea></label><div class="flex items-center justify-between gap-2"><h3 class="font-bold">Ćwiczenia w planie</h3><button id="addSelectedExercise" type="button" class="rounded-xl border px-3 py-2 text-sm font-bold">+ Dodaj zaznaczone</button></div><p class="text-sm text-slate-500">Zaznacz ćwiczenia z bazy poniżej. Każde ćwiczenie w planie ma własne parametry, które możesz dowolnie zmienić.</p><div id="planExerciseRows" class="space-y-3"><p class="text-sm text-slate-500">Dodaj ćwiczenia do planu.</p></div><details class="rounded-2xl border bg-slate-50 p-3"><summary class="cursor-pointer font-bold">＋ Dodaj ćwiczenia z bazy</summary><p class="my-2 text-sm text-slate-500">Rozwiń tylko wtedy, gdy chcesz dodać ćwiczenia do planu.</p><div class="mb-2 flex items-center justify-between gap-2"><span class="text-sm font-semibold">Dostępne ćwiczenia</span><input id="planExerciseSearch" class="w-1/2 rounded-xl border bg-white p-2 text-sm" placeholder="Szukaj"></div><div id="planExercisePicker" class="max-h-52 space-y-2 overflow-auto">Ładowanie…</div></details><button id="savePlan" class="w-full rounded-xl bg-slate-900 p-3 font-bold text-white">Utwórz plan</button><p id="planNotice" class="text-sm"></p></form></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><h2 class="text-xl font-bold">Zapisane plany</h2><div id="templates" class="space-y-3">Ładowanie…</div></section>
</main><nav class="fixed inset-x-0 bottom-0 z-40 border-t bg-white/95 backdrop-blur"><div class="mx-auto grid max-w-3xl grid-cols-5 text-center text-xs font-bold"><a class="p-3" href="/trainingapp/">⌂<br>Home</a><a class="p-3 text-slate-500" href="/trainingapp/calendar.php">▦<br>Kalendarz</a><a class="p-3" href="/trainingapp/workouts.php">◈<br>Treningi</a><a class="p-3 text-slate-500" href="/trainingapp/progress.php">↗<br>Progres</a><a class="p-3 text-slate-500" href="/trainingapp/nutrition.php">◉<br>Dieta</a></div></nav>
<script>
const API='/trainingapp/api';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){const r=await fetch(API+'/'+p,{headers:{'Content-Type':'application/json'},...o});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Błąd API');return d}
let exercises=[],templates=[],planExercises=[];
function exerciseName(id){return exercises.find(x=>Number(x.id)===Number(id))?.name||'Ćwiczenie'}
function exerciseType(id){return exercises.find(x=>Number(x.id)===Number(id))?.exercise_type||'strength'}
function renderPicker(){const q=document.querySelector('#planExerciseSearch').value.toLowerCase(),picked=new Set(planExercises.map(x=>Number(x.exercise_id)));const list=exercises.filter(x=>(x.name+' '+(x.muscle_group||'')).toLowerCase().includes(q));document.querySelector('#planExercisePicker').innerHTML=list.map(x=>'<label class="flex items-center gap-2 rounded-lg border p-2 text-sm"><input type="checkbox" class="picker-check" value="'+x.id+'" '+(picked.has(Number(x.id))?'checked':'')+'><span class="flex-1">'+esc(x.name)+' <span class="text-slate-500">· '+esc(x.muscle_group||'Inne')+'</span></span></label>').join('')||'<p class="text-sm text-slate-500">Brak wyników.</p>'}
function renderPlanRows(){const root=document.querySelector('#planExerciseRows');root.innerHTML=planExercises.map((x,i)=>{const timed=exerciseType(x.exercise_id)==='time';return '<article class="plan-row rounded-2xl border p-3 space-y-3" data-index="'+i+'"><div class="flex items-start gap-2"><div class="flex-1"><p class="font-bold">'+(i+1)+'. '+esc(exerciseName(x.exercise_id))+'</p><p class="text-xs text-slate-500">'+esc(exercises.find(e=>Number(e.id)===Number(x.exercise_id))?.muscle_group||'Inne')+'</p></div><div class="flex gap-1"><button type="button" class="move-up rounded-lg border px-2 py-1" title="Przesuń w górę">↑</button><button type="button" class="move-down rounded-lg border px-2 py-1" title="Przesuń w dół">↓</button><button type="button" class="remove-row rounded-lg border px-2 py-1 text-rose-700">Usuń</button></div></div><div class="grid grid-cols-2 gap-2 sm:grid-cols-3"><label class="text-xs font-semibold text-slate-500">Serie<input data-field="sets_count" type="number" min="1" max="20" value="'+esc(x.sets_count??3)+'" class="mt-1 w-full rounded-lg border p-2 text-sm"></label>'+(timed?'<label class="text-xs font-semibold text-slate-500">Czas na serię (sek.)<input data-field="min_reps" type="number" min="1" max="3600" value="'+esc(x.min_reps??45)+'" class="mt-1 w-full rounded-lg border p-2 text-sm"></label>':'<label class="text-xs font-semibold text-slate-500">Powt. min<input data-field="min_reps" type="number" min="1" max="500" value="'+esc(x.min_reps??8)+'" class="mt-1 w-full rounded-lg border p-2 text-sm"></label><label class="text-xs font-semibold text-slate-500">Powt. max<input data-field="max_reps" type="number" min="1" max="500" value="'+esc(x.max_reps??12)+'" class="mt-1 w-full rounded-lg border p-2 text-sm"></label>')+'<label class="text-xs font-semibold text-slate-500">Przerwa (sek.)<input data-field="rest_seconds" type="number" min="0" max="3600" value="'+esc(x.rest_seconds??90)+'" class="mt-1 w-full rounded-lg border p-2 text-sm"></label><label class="text-xs font-semibold text-slate-500">RIR<input data-field="target_rir" type="number" min="0" max="10" step="0.5" value="'+esc(x.target_rir??'')+'" class="mt-1 w-full rounded-lg border p-2 text-sm" placeholder="opcjonalnie"></label><label class="text-xs font-semibold text-slate-500">Tempo<input data-field="tempo" value="'+esc(x.tempo??'')+'" class="mt-1 w-full rounded-lg border p-2 text-sm" placeholder="np. 3-1-1"></label></div><label class="block text-xs font-semibold text-slate-500">Notatka do ćwiczenia<textarea data-field="notes" rows="2" class="mt-1 w-full rounded-lg border p-2 text-sm" placeholder="Opcjonalnie">'+esc(x.notes??'')+'</textarea></label></article>'}).join('')||'<p class="rounded-xl bg-slate-50 p-3 text-sm text-slate-500">Plan nie ma ćwiczeń. Dodaj je z bazy poniżej.</p>';root.querySelectorAll('.plan-row').forEach(row=>{const i=Number(row.dataset.index);row.querySelectorAll('[data-field]').forEach(input=>input.onchange=()=>{planExercises[i][input.dataset.field]=input.value===''?null:(['tempo','notes'].includes(input.dataset.field)?input.value:Number(input.value))});row.querySelector('.remove-row').onclick=()=>{planExercises.splice(i,1);renderPlanRows();renderPicker()};row.querySelector('.move-up').onclick=()=>{if(i>0){[planExercises[i-1],planExercises[i]]=[planExercises[i],planExercises[i-1]];renderPlanRows()}};row.querySelector('.move-down').onclick=()=>{if(i<planExercises.length-1){[planExercises[i+1],planExercises[i]]=[planExercises[i],planExercises[i+1]];renderPlanRows()}}})}
function renderTemplates(){const root=document.querySelector('#templates');root.innerHTML=templates.map(t=>'<article class="rounded-2xl border p-4"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><h3 class="text-lg font-bold">'+esc(t.name)+'</h3><p class="text-sm text-slate-500">'+esc(t.description||'Bez opisu')+'</p><p class="mt-2 text-sm">'+(t.exercises||[]).length+' ćwiczeń</p></div><button class="archive-plan rounded-xl border px-3 py-2 text-sm" data-id="'+t.id+'">Archiwizuj</button></div><ol class="mt-3 list-inside list-decimal space-y-1 text-sm text-slate-600">'+(t.exercises||[]).map(x=>'<li>'+esc(x.exercise_name)+' — '+x.sets_count+' serii'+(x.exercise_type==='time'?' · '+(x.min_reps||45)+' s':x.min_reps?' · '+x.min_reps+(x.max_reps&&x.max_reps!==x.min_reps?'-'+x.max_reps:'')+' powt.':'')+' · przerwa '+(x.rest_seconds??90)+' s</li>').join('')+'</ol><div class="mt-4 flex flex-wrap gap-2"><button class="edit-plan rounded-xl border px-4 py-3 font-bold" data-id="'+t.id+'">Edytuj plan</button><a class="inline-flex rounded-xl bg-slate-900 px-4 py-3 font-bold text-white" href="/trainingapp/workout.php?template_id='+t.id+'">Rozpocznij trening</a></div></article>').join('')||'<p class="text-slate-500">Nie masz jeszcze planów treningowych.</p>';root.querySelectorAll('.edit-plan').forEach(b=>b.onclick=()=>editPlan(Number(b.dataset.id)));root.querySelectorAll('.archive-plan').forEach(b=>b.onclick=async()=>{if(!confirm('Zarchiwizować ten plan?'))return;try{await api('workout-templates/'+b.dataset.id,{method:'DELETE'});await load()}catch(e){alert(e.message)}})}
async function load(){[exercises,templates]=await Promise.all([api('exercises'),api('workout-templates')]);renderPicker();renderPlanRows();renderTemplates()}
function addExerciseToPlan(id){if(planExercises.some(x=>Number(x.exercise_id)===Number(id)))return;const timed=exerciseType(id)==='time';planExercises.push({exercise_id:Number(id),sets_count:3,min_reps:timed?45:8,max_reps:timed?45:12,rest_seconds:90,target_rir:null,tempo:'',notes:''});renderPlanRows();renderPicker()}
function editPlan(id){const t=templates.find(x=>Number(x.id)===id);if(!t)return;const f=document.querySelector('#planForm');f.elements.id.value=t.id;f.elements.name.value=t.name;f.elements.description.value=t.description||'';planExercises=(t.exercises||[]).map(x=>({exercise_id:Number(x.exercise_id),sets_count:Number(x.sets_count)||3,min_reps:x.min_reps===null?null:Number(x.min_reps),max_reps:x.max_reps===null?null:Number(x.max_reps),rest_seconds:Number(x.rest_seconds??90),target_rir:x.target_rir===null?null:Number(x.target_rir),tempo:x.tempo||'',notes:x.notes||''}));document.querySelector('#planFormTitle').textContent='Edytuj plan treningowy';document.querySelector('#savePlan').textContent='Zapisz zmiany w planie';document.querySelector('#cancelPlanEdit').classList.remove('hidden');renderPlanRows();renderPicker();f.scrollIntoView({behavior:'smooth',block:'start'})}
function resetPlanForm(){const f=document.querySelector('#planForm');f.reset();f.elements.id.value='';planExercises=[];document.querySelector('#planFormTitle').textContent='Utwórz nowy plan';document.querySelector('#savePlan').textContent='Utwórz plan';document.querySelector('#cancelPlanEdit').classList.add('hidden');document.querySelector('#planNotice').textContent='';renderPlanRows();renderPicker()}
document.querySelector('#planExerciseSearch').oninput=renderPicker;
document.querySelector('#addSelectedExercise').onclick=()=>{document.querySelectorAll('.picker-check:checked').forEach(c=>addExerciseToPlan(Number(c.value)));document.querySelector('#planNotice').textContent='Dodano zaznaczone ćwiczenia. Ustaw ich parametry i zapisz plan.'};
document.querySelector('#cancelPlanEdit').onclick=resetPlanForm;
document.querySelector('#planForm').onsubmit=async e=>{e.preventDefault();const f=e.target,id=f.elements.id.value;if(!planExercises.length){document.querySelector('#planNotice').textContent='Dodaj przynajmniej jedno ćwiczenie.';document.querySelector('#planNotice').className='text-sm text-red-600';return}const payload={name:f.elements.name.value.trim(),description:f.elements.description.value,exercises:planExercises.map(x=>({...x,sets_count:Number(x.sets_count)||3,rest_seconds:Number(x.rest_seconds??90),min_reps:x.min_reps===''?null:x.min_reps,max_reps:x.max_reps===''?null:x.max_reps,target_rir:x.target_rir===''?null:x.target_rir}))};try{await api(id?'workout-templates/'+id:'workout-templates',{method:id?'PUT':'POST',body:JSON.stringify(payload)});document.querySelector('#planNotice').textContent=id?'Plan został zaktualizowany.':'Plan został utworzony.';document.querySelector('#planNotice').className='text-sm text-emerald-700';resetPlanForm();await load()}catch(err){document.querySelector('#planNotice').textContent=err.message;document.querySelector('#planNotice').className='text-sm text-red-600'}};
load().catch(e=>{document.querySelector('#templates').textContent=e.message;document.querySelector('#planExercisePicker').textContent='Nie udało się pobrać ćwiczeń.'});
</script></body></html>